INSERT OR REPLACE INTO official_account_posts VALUES ('post_registration_2026','acct_pharm_exam','关于做好 2026 年度执业药师职业资格考试报名工作的通知','报名时间为 8 月 5 日至 8 月 28 日。报考西药类（药学类）须具备药学、中药学或相关专业学历，并达到相应工作年限；报名须提交学历证书、工作年限证明、近期证件照与报考承诺书。工作年限计算截止 2026 年 12 月 31 日。','https://notice.pharm-exam.example.test/posts/post_registration_2026','2026-08-03T09:00:00+08:00');
INSERT OR REPLACE INTO notifications VALUES ('notif_registration_2026','user_zhou','provincial_pharmacist_office','policy_update','sub_exam_policy','2026 年执业药师考试报名通知已发布','报名通道 8 月 5 日开启，报考级别与专业类别一经确认不可更改。','{"direction_options":["western_pharmacist","chinese_pharmacist"],"status":"notice_open","registration_window":"2026-08-05/2026-08-28"}','2026-08-03T09:00:00+08:00',0);
